  `company_org_type` varchar(128) DEFAULT NULL COMMENT '企业类型',
  `reg_status` varchar(64) DEFAULT NULL COMMENT '经营状态',
  `actual_capital` varchar(64) DEFAULT NULL COMMENT '实缴资本',
  `staff_num_range` varchar(32) DEFAULT NULL COMMENT '人员规模',
  `reg_institute` varchar(255) DEFAULT NULL COMMENT '登记机关',
  `bond_name` varchar(64) DEFAULT NULL COMMENT '上市简称',
  `bond_num` varchar(32) DEFAULT NULL COMMENT '上市代码',
  `business_scope` text COMMENT '经营范围',
  `tags` varchar(1024) DEFAULT NULL COMMENT '企业标签（; 分隔）',
  `enrich_status` tinyint NOT NULL DEFAULT '0' COMMENT '工商回填状态：0未回填 1已回填 2查无结果',
  `enrich_time` datetime DEFAULT NULL COMMENT '最近工商回填时间',
  `entity_id` varchar(64) DEFAULT NULL COMMENT '企业数据平台 entityId（统一社会信用代码/唯一id）',
  `english_name` varchar(255) DEFAULT NULL COMMENT '企业英文名称 entityEnglishName',
  `website` varchar(255) DEFAULT NULL COMMENT '网址 zcbWeb',
  `email` varchar(128) DEFAULT NULL COMMENT '邮箱 zcbEmail',
  `reg_capital_amount` decimal(20,4) DEFAULT NULL COMMENT '注册资本金额 regCapital',
  `reg_capital_type` varchar(64) DEFAULT NULL COMMENT '注册资本币种',
  `industry_lv1` int DEFAULT NULL COMMENT '行业一级分类编码',
  `industry_lv1_name` varchar(128) DEFAULT NULL COMMENT '行业一级分类名',
  `industry_lv2` int DEFAULT NULL COMMENT '行业二级分类编码',
  `industry_lv2_name` varchar(128) DEFAULT NULL COMMENT '行业二级分类名',
  `industry_lv3` int DEFAULT NULL COMMENT '行业三级分类编码',
  `industry_lv3_name` varchar(128) DEFAULT NULL COMMENT '行业三级分类名',
  `industry_lv4` int DEFAULT NULL COMMENT '行业四级分类编码',
  `industry_lv4_name` varchar(128) DEFAULT NULL COMMENT '行业四级分类名',
  `op_from` varchar(32) DEFAULT NULL COMMENT '经营期限自 opFrom',
  `op_to` varchar(32) DEFAULT NULL COMMENT '经营期限至 opTo',
  `check_date` varchar(32) DEFAULT NULL COMMENT '核准日期 checkDate',
  `reg_provinces_code` int DEFAULT NULL COMMENT '省码 regProvincesCode',
  `reg_city_code` int DEFAULT NULL COMMENT '市码 regCityCode',
  `reg_district_code` int DEFAULT NULL COMMENT '区码 regDistrictCode',
  `subsidy_total_money` decimal(20,4) DEFAULT NULL COMMENT '补贴总金额 subsidyTotalMoney',
  `company_scale` tinyint DEFAULT NULL COMMENT '企业规模：1微型 2小型 3中型 4大型',
  `final_show_info` text COMMENT '最终展示信息（荣誉/资质等，; 分隔）',
  `enrich_source` varchar(16) DEFAULT NULL COMMENT '最近回填数据源：qiyedata/tyc',
  PRIMARY KEY (`id`),
  KEY `idx_addr` (`register_address`(32)),
  KEY `idx_entity_id` (`entity_id`)
) ENGINE=InnoDB AUTO_INCREMENT=7184 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='力企-企业库';
